import { error } from "@sveltejs/kit";
import { getAllCategories } from "../../../chunks/database.js";
async function load() {
  try {
    const categories = await getAllCategories();
    return {
      categories
    };
  } catch (e) {
    console.error("Error loading categories:", e);
    throw error(500, "Erro ao carregar categorias");
  }
}
export {
  load
};
